SET NAMES utf8mb4;
CREATE TABLE IF NOT EXISTS users (
 id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT,name VARCHAR(180) NOT NULL,email VARCHAR(255) UNIQUE,password_hash VARCHAR(255),role VARCHAR(30) NOT NULL DEFAULT 'user',status VARCHAR(30) NOT NULL DEFAULT 'active',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
INSERT IGNORE INTO users (id,name,role) VALUES (1,'Internal workspace','admin');
CREATE TABLE IF NOT EXISTS projects (
 id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT,user_id BIGINT UNSIGNED NOT NULL,name VARCHAR(180) NOT NULL,video_idea TEXT NOT NULL,video_goal VARCHAR(100) NOT NULL,mode VARCHAR(20) NOT NULL DEFAULT 'simple',status VARCHAR(30) NOT NULL DEFAULT 'draft',duration INT NOT NULL DEFAULT 15,aspect_ratio VARCHAR(10) NOT NULL,platform VARCHAR(60) NOT NULL,ai_video_model VARCHAR(60) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY (user_id) REFERENCES users(id),INDEX(user_id,updated_at)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS assets (
 id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT,user_id BIGINT UNSIGNED NOT NULL,asset_type VARCHAR(30) NOT NULL,original_filename VARCHAR(255) NOT NULL,reference_name VARCHAR(100) NOT NULL UNIQUE,stored_filename VARCHAR(100) NOT NULL,storage_path VARCHAR(255) NOT NULL,mime_type VARCHAR(50) NOT NULL,file_size INT UNSIGNED NOT NULL,width INT UNSIGNED,height INT UNSIGNED,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id),INDEX(user_id,asset_type)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS products (
 id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT,user_id BIGINT UNSIGNED NOT NULL,name VARCHAR(180) NOT NULL,reference_asset_id BIGINT UNSIGNED NULL,description TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id),FOREIGN KEY(reference_asset_id) REFERENCES assets(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS characters (
 id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT,user_id BIGINT UNSIGNED NOT NULL,name VARCHAR(180) NOT NULL,reference_asset_id BIGINT UNSIGNED NULL,description TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id),FOREIGN KEY(reference_asset_id) REFERENCES assets(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS brands (
 id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT,user_id BIGINT UNSIGNED NOT NULL,name VARCHAR(180) NOT NULL,description TEXT,primary_colors TEXT,secondary_colors TEXT,visual_style TEXT,tone TEXT,brand_do TEXT,brand_dont TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS project_settings (
 id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT,project_id BIGINT UNSIGNED NOT NULL UNIQUE,character_id BIGINT UNSIGNED NULL,brand_id BIGINT UNSIGNED NULL,product_id BIGINT UNSIGNED NULL,config_json LONGTEXT NOT NULL,scene_json LONGTEXT,action_json LONGTEXT,visual_style_json LONGTEXT,camera_json LONGTEXT,color_json LONGTEXT,dialogue_json LONGTEXT,audio_json LONGTEXT,advanced_json LONGTEXT,FOREIGN KEY(project_id) REFERENCES projects(id) ON DELETE CASCADE,CHECK(JSON_VALID(config_json))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS templates (
 id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT,user_id BIGINT UNSIGNED NULL,name VARCHAR(180) NOT NULL,description TEXT,config_json LONGTEXT NOT NULL,is_system BOOLEAN DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,CHECK(JSON_VALID(config_json))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS prompt_generations (
 id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT,project_id BIGINT UNSIGNED NOT NULL,master_prompt LONGTEXT NOT NULL,short_prompt TEXT NOT NULL,negative_prompt TEXT NOT NULL,shots_json LONGTEXT NOT NULL,target_model VARCHAR(60) NOT NULL,project_snapshot_json LONGTEXT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(project_id) REFERENCES projects(id) ON DELETE CASCADE,INDEX(project_id,created_at)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
